import nltk
from string import punctuation
import pandas as pd

def task_func(text):
    if not isinstance(text, str):
        raise ValueError("text must be a string")

    counts = {}
    order = []

    for token in text.split():
        if token.startswith("$") and not all(ch in punctuation for ch in token):
            if token not in counts:
                counts[token] = 0
                order.append(token)
            counts[token] += 1

    return pd.DataFrame(
        {
            "Word": order,
            "Frequency": [counts[word] for word in order],
        }
    )
